<?php $title = 'Zamówienia | ShopStack'; require __DIR__ . '/../layouts/header.php'; ?><p class="eyebrow">KONTO / HISTORIA</p><h1>Twoje zamówienia</h1><?php foreach ($orders as $order): ?><section class="order"><div class="order-head"><strong>#<?= e($order['id']) ?></strong><span><?= e($order['status']) ?></span><span><?= e($order['created_at']) ?></span><strong><?= money($order['total_amount']) ?></strong></div><?php foreach ($order['items'] as $item): ?><p><?= e($item['product_name']) ?> × <?= e($item['quantity']) ?> <span><?= money($item['subtotal']) ?></span></p><?php endforeach; ?></section><?php endforeach; ?><?php if (!$orders): ?><p class="muted">Nie masz jeszcze zamówień.</p><?php endif; ?><?php require __DIR__ . '/../layouts/footer.php'; ?>
